async Task ConsumeAsync(string body, CancellationToken ct)
{
    try
    {
        await HandleAsync(body, ct);
    }
    catch (OperationCanceledException) when (ct.IsCancellationRequested)
    {
        throw;
    }
    catch (TimeoutException ex)
    {
        Log(ex);
        throw; // host: retry / DLQ policy
    }
}
